  "name": "o3-ozone-interaction-id",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "An interaction ID generated by Ozone if the caller did not send in one. If the callerInteractionId is specified, this takes the same value."
}

