  "name": "o3-psu-identifier",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "A Base64 encoded representation of the psuIdentifier JSON object."
}

{
  "description": "Response to a request to the Debtor details for a given payment, in order to initiate a refund. Requires the consent of the Debtor to be retrieved, enforced at the API Hub.",
  "type": "object",
  "properties": {
    "data": {
      "$ref": "#/components/schemas/RefundGetResponseBody"
    },
    "meta": {
      "$ref": "#/components/schemas/Meta"
    }
  }
}

{
  "description": "Primary data for the response",
  "type": "object",
  "required": [
    "refundAccount"
  ],
  "properties": {
    "consentId": {
      "description": "Unique identification assigned by the TPP to identify the consent resource.\n",
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "refundAccount": {
      "$ref": "#/components/schemas/AEDebtorAccount"
    }
  }
}

{
  "description": "Unambiguous identification of the account of the debtor to which a debit entry will be made.",
  "type": "object",
  "required": [
    "schemeName",
    "identification",
    "name"
  ],
  "properties": {
    "schemeName": {
      "description": "Name of the identification scheme, in a coded form as published in an external list.",
      "type": "string",
      "enum": [
        "IBAN"
      ]
    },
    "identification": {
      "description": "Identification for the account assigned by the LFI based on the Account Scheme Name.\nThis identification is known by the User account owner.\n",
      "type": "string",
      "minLength": 1
    },
    "name": {
      "$ref": "#/components/schemas/AEName"
    }
  }
}

{
  "type": "object",
  "description": "The Account Holder Name is the name or names of the Account owner(s) represented at the account level\n",
  "properties": {
    "en": {
      "type": "string",
      "description": "English value of the string",
      "maxLength": 70
    },
    "ar": {
      "type": "string",
      "description": "Arabic value of the string",
      "maxLength": 70
    }
  },
  "additionalProperties": false
}

{
  "description": "Metadata relevant to the resource.",
  "type": "object",
  "additionalProperties": false
}

{
  "description": "Operation failed due to a invalid request parameter",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error400"
      }
    }
  }
}

{
  "description": "Default error response payload structure for Ozone Connect",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation. organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "Consent.Invalid",
            "Consent.BusinessRuleViolation",
            "Consent.FailsControlParameters",
            "Consent.InvalidUserIdentifier",
            "JWS.InvalidSignature",
            "JWS.Malformed",
            "JWS.InvalidClaim",
            "JWS.InvalidHeader",
            "JWE.DecryptionError",
            "JWE.InvalidHeader",
            "GenericRecoverableError",
            "GenericError",
            "Event.UnexpectedEvent",
            "Body.InvalidFormat",
            "Resource.InvalidFormat"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
  "description": "Message describing what problem has occurred",
  "type": "string"
}

{
  "description": "Operation failed as access to the requested resource is forbidden",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error403"
      }
    }
  }
}

{
  "description": "Error code identifying the problem that occurred. The first part of the code is the namespace, which is the name of the organisation or system that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "AccessToken.InvalidScope",
            "Consent.TransientAccountAccessFailure",
            "Consent.AccountTemporarilyBlocked",
            "Consent.PermanentAccountAccessFailure",
            "GenericRecoverableError",
            "GenericError"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
  "description": "Operation failed due to an internal server error",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error500"
      }
    }
  }
}

{
  "description": "Error code identifying the problem that occurred. The first part of the code is the namespace, which is the name of the organisation or system that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "GenericRecoverableError",
            "GenericError"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

